<?php
// Preserve the three legacy art-commission screens shipped in the original repository.
$commissions=json_decode(file_get_contents(__DIR__.'/seed-commissions.json'));
$recentCommissions=$commissions;usort($recentCommissions,fn($a,$b)=>strcmp($b->updatedAt,$a->updatedAt));$recentCommissions=array_slice($recentCommissions,0,5);
$stats=(object)['total'=>count($commissions),'completed'=>count(array_filter($commissions,fn($c)=>$c->status==='completed')),'inProgress'=>count(array_filter($commissions,fn($c)=>$c->status==='in_progress')),'totalRevenue'=>array_sum(array_map(fn($c)=>$c->price,$commissions))];
$statusData=$artworkTypeData=[];foreach($commissions as $c){$s=getCategoryDisplayName($c->status);$t=getCategoryDisplayName($c->artworkType);$statusData[$s]=($statusData[$s]??0)+1;$artworkTypeData[$t]=($artworkTypeData[$t]??0)+1;}
$monthlyData=[];for($i=5;$i>=0;$i--){$d=strtotime("first day of -$i month");$m=array_filter($commissions,fn($c)=>date('Y-m',strtotime($c->createdAt))===date('Y-m',$d));$monthlyData[]=(object)['month'=>date('M',$d),'revenue'=>array_sum(array_map(fn($c)=>$c->price,$m)),'commissions'=>count($m)];}
$impactMetrics=(object)['totalRevenue'=>$stats->totalRevenue,'jobsSupported'=>ceil($stats->totalRevenue/30000),'averageIncome'=>$stats->total?$stats->totalRevenue/$stats->total:0,'productivityGain'=>$stats->completed*8,'entrepreneurshipSupport'=>$stats->total,'sustainableIncome'=>$stats->completed?$stats->totalRevenue/$stats->completed:0,'economicGrowthContribution'=>$stats->totalRevenue*.15];
function getCompletionRate(): float { $s=$GLOBALS['stats'];return $s->total?$s->completed/$s->total*100:0; }
function getAverageCommissionValue(): float { $s=$GLOBALS['stats'];return $s->total?$s->totalRevenue/$s->total:0; }
function getSdgTargets(): array { $m=$GLOBALS['impactMetrics'];return [(object)['target'=>'8.1','description'=>'Sustain economic growth per capita','achieved'=>$m->totalRevenue>1000],(object)['target'=>'8.2','description'=>'Achieve higher levels of economic productivity','achieved'=>$m->productivityGain>20],(object)['target'=>'8.3','description'=>'Promote development-oriented policies that support productive activities','achieved'=>$m->entrepreneurshipSupport>0],(object)['target'=>'8.6','description'=>'Substantially reduce the proportion of youth not in employment','achieved'=>$m->jobsSupported>0],(object)['target'=>'8.10','description'=>'Strengthen the capacity of domestic financial institutions','achieved'=>$m->averageIncome>100]]; }
